def main():
 r=json.loads((ROOT/'results/summary.json').read_text());extra=json.loads((ROOT/'results/attachment_readout.json').read_text());a,b=r['arms'];audit=r['audit'];final=pd.read_csv(ROOT/'results/final_candidates.csv');initial=r['initial_RF_mean']
